//! Shared by `ts_contract.rs` and `fixtures.rs`: the TypeScript generator
//! and the canonical fixtures (design §50 §8.2–§8.3, plan DD1 Task 9).
//!
//! Everything under `web/packages/agentd-client/src/gen/`, plus
//! `src/fixtures.gen.ts`, is written by [`generate`]; the fixtures under
//! `crates/loams-agentd-proto/fixtures/` by [`write_fixtures`]. Both are
//! regenerated by `cargo test -p loams-agentd-proto export_bindings`.

#![allow(dead_code)] // Each test binary uses a different part.

pub mod fixtures;

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;
use std::sync::atomic::{AtomicUsize, Ordering};

use loams_agentd_proto::rpc::{
    AGENTD_PROTOCOL, ERROR_REASONS, METHODS, Method, MethodKind, MethodVisitor, Role, visit_methods,
};
use serde::Serialize;
use serde::de::DeserializeOwned;
use ts_rs::{Config, TS};

/// The repository root.
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// `web/packages/agentd-client`.
pub fn client_dir() -> PathBuf {
    repo_root().join("web/packages/agentd-client")
}

/// `crates/loams-agentd-proto/fixtures`.
pub fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures")
}

/// A fresh scratch directory under the target directory (never `/tmp`),
/// unique per call: tests in one process run in parallel.
pub fn scratch(name: &str) -> PathBuf {
    static NEXT: AtomicUsize = AtomicUsize::new(0);
    let n = NEXT.fetch_add(1, Ordering::Relaxed);
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("agentd-proto")
        .join(format!("{name}-{}-{n}", std::process::id()));
    if dir.exists() {
        std::fs::remove_dir_all(&dir).expect("clear scratch dir");
    }
    std::fs::create_dir_all(&dir).expect("create scratch dir");
    dir
}

/// How the bindings are rendered: 64-bit integers are JSON numbers, so they
/// are `number` in TypeScript, not `bigint`.
pub fn ts_config(out: &Path) -> Config {
    Config::new().with_large_int("number").with_out_dir(out)
}

/// The generated files, by path relative to `web/packages/agentd-client/src`.
pub type Files = BTreeMap<String, String>;

/// Every generated file under `src/` (the `gen/` tree and `fixtures.gen.ts`).
pub fn generate() -> Files {
    let work = scratch("generate");
    let gen_dir = work.join("gen");
    let cfg = ts_config(&gen_dir);

    // The types: every method's params and result, every fixture's type,
    // and everything they reference.
    struct Export<'a>(&'a Config, BTreeSet<String>);
    impl MethodVisitor for Export<'_> {
        fn visit<M: Method>(&mut self) {
            export::<M::Params>(self.0);
            export::<M::Result>(self.0);
            self.1.insert(M::Params::name(self.0));
            self.1.insert(M::Result::name(self.0));
        }
    }
    let mut export_types = Export(&cfg, BTreeSet::new());
    visit_methods(&mut export_types);
    let fixtures = fixtures::all();
    for fixture in &fixtures {
        (fixture.export)(&cfg);
    }

    let mut files: Files = read_tree(&gen_dir, |_| true)
        .into_iter()
        .map(|(rel, text)| (format!("gen/{rel}"), text))
        .collect();
    let types: Vec<String> = files
        .keys()
        .map(|path| {
            path.trim_start_matches("gen/")
                .trim_end_matches(".ts")
                .to_owned()
        })
        .collect();
    files.insert("gen/index.ts".into(), index_ts(&types));
    files.insert("gen/methods.ts".into(), methods_ts());
    files.insert("fixtures.gen.ts".into(), fixtures_ts(&fixtures));
    std::fs::remove_dir_all(&work).ok();
    files
}

fn export<T: TS + 'static>(cfg: &Config) {
    if T::output_path().is_some() {
        T::export_all(cfg).unwrap_or_else(|e| panic!("export {}: {e}", T::name(cfg)));
    }
}

const HEADER: &str = "// Generated by `cargo test -p loams-agentd-proto export_bindings` (plan DD1 Task 9).\n// Do not edit this file manually.\n";

/// `gen/index.ts`, re-exporting every type by its file (`path` without `.ts`).
fn index_ts(paths: &[String]) -> String {
    let mut out = String::from(HEADER);
    for path in paths {
        let ty = path.rsplit('/').next().unwrap();
        writeln!(out, "export type {{ {ty} }} from \"./{path}\";").unwrap();
    }
    out
}

fn role(role: Role) -> &'static str {
    match role {
        Role::Owner => "owner",
        Role::Mcp => "mcp",
    }
}

fn kind(kind: MethodKind) -> &'static str {
    match kind {
        MethodKind::Unary => "unary",
        MethodKind::Stream => "stream",
    }
}

/// `gen/methods.ts`: the table as a value and as the `Methods` type map.
fn methods_ts() -> String {
    let mut out = String::from(HEADER);
    let imports: BTreeSet<&str> = METHODS
        .iter()
        .flat_map(|m| [m.params, m.result])
        .chain(["Role"])
        .collect();
    for ty in &imports {
        writeln!(out, "import type {{ {ty} }} from \"./{ty}\";").unwrap();
    }
    out.push('\n');
    writeln!(
        out,
        "/** The wire protocol `Hello` must name (`AGENTD_PROTOCOL`). */"
    )
    .unwrap();
    writeln!(out, "export const AGENTD_PROTOCOL = {AGENTD_PROTOCOL};").unwrap();
    out.push('\n');
    out.push_str(
        "/** Every `{err}` reason prefix; an `AgentdError`'s `code` is one of these. */\n",
    );
    out.push_str("export const ERROR_CODES = [\n");
    for reason in ERROR_REASONS {
        writeln!(out, "  \"{reason}\",").unwrap();
    }
    out.push_str("] as const;\n\nexport type AgentdErrorCode = (typeof ERROR_CODES)[number];\n\n");
    out.push_str(
        "/** One row of the daemon's method table (`loams_agentd_proto::rpc::METHODS`). */\n\
         export interface MethodSpec {\n  name: string;\n  kind: \"unary\" | \"stream\";\n  \
         params: string;\n  result: string;\n  role: Role;\n  renderer: boolean;\n}\n\n",
    );
    out.push_str("export const METHODS = [\n");
    for m in METHODS {
        writeln!(
            out,
            "  {{ name: \"{}\", kind: \"{}\", params: \"{}\", result: \"{}\", role: \"{}\", renderer: {} }},",
            m.name,
            kind(m.kind),
            m.params,
            m.result,
            role(m.role),
            m.renderer
        )
        .unwrap();
    }
    out.push_str("] as const satisfies readonly MethodSpec[];\n\n");
    out.push_str(
        "/** Each method's params, result (or stream item), kind, role and renderer flag. */\n",
    );
    out.push_str("export type Methods = {\n");
    for m in METHODS {
        writeln!(
            out,
            "  {}: {{ params: {}; result: {}; kind: \"{}\"; role: \"{}\"; renderer: {} }};",
            m.name,
            m.params,
            m.result,
            kind(m.kind),
            role(m.role),
            m.renderer
        )
        .unwrap();
    }
    out.push_str("};\n\n");
    out.push_str(
        "export type MethodName = keyof Methods;\n\
         export type Params<M extends MethodName> = Methods[M][\"params\"];\n\
         export type Result<M extends MethodName> = Methods[M][\"result\"];\n\
         export type UnaryMethod = { [M in MethodName]: Methods[M][\"kind\"] extends \"unary\" ? M : never }[MethodName];\n\
         export type StreamMethod = { [M in MethodName]: Methods[M][\"kind\"] extends \"stream\" ? M : never }[MethodName];\n\
         export type Item<M extends StreamMethod> = Methods[M][\"result\"];\n\
         export type RendererMethod = { [M in MethodName]: Methods[M][\"renderer\"] extends true ? M : never }[MethodName];\n\
         export type RendererUnary = RendererMethod & UnaryMethod;\n\
         export type RendererStream = RendererMethod & StreamMethod;\n",
    );
    out
}

/// `fixtures.gen.ts`: every fixture as a constant that must satisfy its type.
fn fixtures_ts(fixtures: &[Fixture]) -> String {
    let mut out = String::from(HEADER);
    let types: BTreeSet<&str> = fixtures.iter().map(|f| f.ts_type.as_str()).collect();
    for ty in &types {
        writeln!(out, "import type {{ {ty} }} from \"./gen/{ty}\";").unwrap();
    }
    out.push('\n');
    for fixture in fixtures {
        let json = serde_json::to_string_pretty(&canonical(&fixture.value)).unwrap();
        writeln!(
            out,
            "export const {} = {} satisfies {};\n",
            fixture.ident(),
            json,
            fixture.ts_type
        )
        .unwrap();
    }
    out.push_str("/** Every fixture with its type's name, for the reducer and decoder tests. */\n");
    out.push_str("export const FIXTURES = [\n");
    for fixture in fixtures {
        writeln!(
            out,
            "  {{ name: \"{}\", type: \"{}\", value: {} }},",
            fixture.name,
            fixture.ts_type,
            fixture.ident()
        )
        .unwrap();
    }
    out.push_str("] as const;\n");
    out
}

/// One canonical value of a wire type.
pub struct Fixture {
    /// `Type` or `Type.variant`.
    pub name: String,
    /// The TypeScript name of its type.
    pub ts_type: String,
    pub value: serde_json::Value,
    /// Deserialize `value` as the type and serialize it again.
    pub roundtrip: fn(&serde_json::Value) -> Result<serde_json::Value, String>,
    export: fn(&Config),
}

impl Fixture {
    pub fn new<T: Serialize + DeserializeOwned + TS + 'static>(name: &str, value: T) -> Self {
        Self {
            name: name.to_owned(),
            ts_type: T::name(&ts_config(Path::new("."))),
            value: serde_json::to_value(value).expect("serialize fixture"),
            roundtrip: |value| {
                let typed: T = serde_json::from_value(value.clone()).map_err(|e| e.to_string())?;
                serde_json::to_value(typed).map_err(|e| e.to_string())
            },
            export: export::<T>,
        }
    }

    /// The constant's name in `fixtures.gen.ts`.
    pub fn ident(&self) -> String {
        format!("fixture_{}", self.name.replace(['.', '-'], "_"))
    }

    /// Its file under `fixtures/`.
    pub fn file_name(&self) -> String {
        format!("{}.json", self.name)
    }
}

/// `value` with object keys sorted, so the files do not depend on field
/// order or on hash-map iteration.
pub fn canonical(value: &serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Object(map) => {
            let sorted: BTreeMap<&String, serde_json::Value> =
                map.iter().map(|(k, v)| (k, canonical(v))).collect();
            serde_json::Value::Object(sorted.into_iter().map(|(k, v)| (k.clone(), v)).collect())
        }
        serde_json::Value::Array(items) => {
            serde_json::Value::Array(items.iter().map(canonical).collect())
        }
        other => other.clone(),
    }
}

/// The fixture files, by name under `fixtures/`.
pub fn fixture_files() -> Files {
    fixtures::all()
        .iter()
        .map(|f| {
            let text = serde_json::to_string_pretty(&canonical(&f.value)).unwrap() + "\n";
            (f.file_name(), text)
        })
        .collect()
}

/// The files under `root` (recursively, `/`-separated relative paths) that
/// `pick` accepts.
pub fn read_tree(root: &Path, pick: impl Fn(&str) -> bool) -> Files {
    fn walk(root: &Path, dir: &Path, pick: &dyn Fn(&str) -> bool, out: &mut Files) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries {
            let path = entry.expect("dir entry").path();
            if path.is_dir() {
                walk(root, &path, pick, out);
                continue;
            }
            let rel = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");
            if pick(&rel) {
                out.insert(rel, std::fs::read_to_string(&path).expect("read file"));
            }
        }
    }
    let mut out = Files::new();
    walk(root, root, &pick, &mut out);
    out
}

/// The generated files as they are in the working tree.
pub fn committed_bindings() -> &'static Files {
    static COMMITTED: OnceLock<Files> = OnceLock::new();
    COMMITTED.get_or_init(|| {
        read_tree(&client_dir().join("src"), |rel| {
            rel.starts_with("gen/") || rel == "fixtures.gen.ts"
        })
    })
}

/// Write `fixtures/*.json` from the typed constructors (after reading the
/// committed state, for `fixtures_roundtrip` in the same process).
pub fn write_fixtures() {
    committed_fixtures();
    write_tree(
        &fixtures_dir(),
        |rel| rel.ends_with(".json"),
        &fixture_files(),
    );
}

/// The fixture files as they are in the working tree.
pub fn committed_fixtures() -> &'static Files {
    static COMMITTED: OnceLock<Files> = OnceLock::new();
    COMMITTED.get_or_init(|| read_tree(&fixtures_dir(), |rel| rel.ends_with(".json")))
}

/// Replace the files under `root` that `owned` accepts with `files`.
pub fn write_tree(root: &Path, owned: impl Fn(&str) -> bool, files: &Files) {
    for stale in read_tree(root, &owned).keys() {
        if !files.contains_key(stale) {
            std::fs::remove_file(root.join(stale)).expect("remove stale file");
        }
    }
    for (rel, text) in files {
        let path = root.join(rel);
        std::fs::create_dir_all(path.parent().unwrap()).expect("create dir");
        if std::fs::read_to_string(&path).ok().as_deref() != Some(text.as_str()) {
            std::fs::write(&path, text).expect("write file");
        }
    }
}

/// A readable list of the paths that differ.
pub fn diff(expected: &Files, actual: &Files) -> Vec<String> {
    let mut out = Vec::new();
    for (path, text) in expected {
        match actual.get(path) {
            None => out.push(format!("missing: {path}")),
            Some(other) if other != text => out.push(format!("stale: {path}")),
            Some(_) => {}
        }
    }
    for path in actual.keys() {
        if !expected.contains_key(path) {
            out.push(format!("not generated: {path}"));
        }
    }
    out
}
